(() => {
  const $ = id => document.getElementById(id);
  let refreshTick = 0;
  const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));
  const signed = value => `${Number(value) >= 0 ? '+' : ''}${Number(value || 0).toFixed(2)}%`;
  const request = async (url, options = {}) => { const response = await fetch(url, {headers:{'Content-Type':'application/json', ...(options.headers || {})}, ...options}); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.detail || '数据请求失败'); return data; };
  const ma = (values, n) => values.map((_, i) => i < n - 1 ? null : values.slice(i - n + 1, i + 1).reduce((a, b) => a + b, 0) / n);
  const linePoints = (values, low, high, width, height, padX, padY) => values.map((value, index) => value == null ? null : `${padX + index / Math.max(values.length - 1, 1) * (width - padX * 2)},${padY + (high - value) / Math.max(high - low, .01) * (height - padY * 2)}`).filter(Boolean).join(' ');
  const candlestick = bars => {
    const view = bars.slice(-90), width = 1000, height = 440, chartHeight = 328, padX = 26, padY = 16;
    const lows = view.map(row => Number(row.low)), highs = view.map(row => Number(row.high)), min = Math.min(...lows), max = Math.max(...highs), range = Math.max(max - min, .01);
    const y = value => padY + (max - Number(value)) / range * (chartHeight - padY * 2), x = index => padX + index / Math.max(view.length - 1, 1) * (width - padX * 2), maxVol = Math.max(...view.map(row => Number(row.volume)), 1);
    const candles = view.map((row, index) => { const up = Number(row.close) >= Number(row.open), color = up ? '#ef5350' : '#2ca87f', cx = x(index), top = Math.min(y(row.open), y(row.close)), body = Math.max(Math.abs(y(row.open)-y(row.close)), 1.2); return `<g><line x1="${cx}" x2="${cx}" y1="${y(row.high)}" y2="${y(row.low)}" stroke="${color}" stroke-width="1.2"/><rect x="${cx-2.6}" y="${top}" width="5.2" height="${body}" fill="${color}"/><rect x="${cx-2.6}" y="${chartHeight + 14 + (1-Number(row.volume)/maxVol)*70}" width="5.2" height="${Number(row.volume)/maxVol*70}" fill="${color}" opacity=".6"/></g>`; }).join('');
    const closes = view.map(row => Number(row.close));
    return `<svg class="qt-canvas" viewBox="0 0 ${width} ${height}" role="img" aria-label="日K与成交量"><rect width="100%" height="100%" rx="12" fill="#0c1729"/>${[.2,.4,.6,.8].map(p=>`<line x1="${padX}" x2="${width-padX}" y1="${padY+p*(chartHeight-padY*2)}" y2="${padY+p*(chartHeight-padY*2)}" stroke="#31425f" stroke-width=".8"/>`).join('')}<polyline points="${linePoints(ma(closes,5),min,max,width,chartHeight,padX,padY)}" fill="none" stroke="#f5b942" stroke-width="1.4"/><polyline points="${linePoints(ma(closes,20),min,max,width,chartHeight,padX,padY)}" fill="none" stroke="#52b5ff" stroke-width="1.4"/>${candles}<text x="${padX}" y="${chartHeight+112}" fill="#95a7c6" font-size="13">${view[0]?.date || ''}</text><text x="${width-120}" y="${chartHeight+112}" fill="#95a7c6" font-size="13">${view.at(-1)?.date || ''}</text></svg>`;
  };
  const openQuant = () => { document.querySelectorAll('.page').forEach(page => page.classList.remove('active')); document.querySelectorAll('.nav button').forEach(button => button.classList.remove('active')); $('quant').classList.add('active'); $('quantNav').classList.add('active'); $('title').textContent = '量化研究终端'; };
  const selectSymbol = async symbol => {
    $('qtSymbol').value = symbol; $('qtSymbolTitle').textContent = `${symbol.toUpperCase()} · 加载中`; $('qtChart').innerHTML = '<div class="qt-empty">正在加载前复权日 K、均线与成交量…</div>';
    try { const data = await request(`/api/quant/daily-kline/${encodeURIComponent(symbol)}?days=360`); const last = data.bars.at(-1), previous = data.bars.at(-2), change = (Number(last.close) / Number(previous.close) - 1) * 100; $('qtSymbolTitle').textContent = `${data.name} · ${data.symbol}`; $('qtQuote').innerHTML = `<strong>${Number(last.close).toFixed(2)}</strong><span class="${change>=0?'up':'down'}">${signed(change)}</span><em>${data.adjustment} · ${data.source}</em>`; $('qtChart').innerHTML = candlestick(data.bars); $('qtStats').innerHTML = `<span>开 ${Number(last.open).toFixed(2)}</span><span>高 ${Number(last.high).toFixed(2)}</span><span>低 ${Number(last.low).toFixed(2)}</span><span>量 ${Number(last.volume).toLocaleString()}</span><span>MA5 ${ma(data.bars.map(b=>Number(b.close)),5).at(-1)?.toFixed(2)}</span><span>MA20 ${ma(data.bars.map(b=>Number(b.close)),20).at(-1)?.toFixed(2)}</span>`; $('qtBacktest').dataset.symbol = symbol; } catch(error) { $('qtSymbolTitle').textContent = '未能加载日 K'; $('qtChart').innerHTML = `<div class="qt-error">${escapeHtml(error.message)}</div>`; }
  };
  const renderMap = data => { $('qtUpdated').textContent = `更新 ${data.updated_at} · ${data.source}`; $('qtCloud').innerHTML = data.groups.map(group => `<section class="qt-sector"><header><b>${escapeHtml(group.label)}</b><span class="${group.change_pct>=0?'up':'down'}">${signed(group.change_pct)}</span></header><div class="qt-tilegrid">${group.items.map(item => `<button class="qt-tile ${item.change_pct>=0?'rise':'fall'}" data-symbol="${escapeHtml(item.symbol)}"><small>${escapeHtml(item.name)}</small><strong>${Number(item.price).toFixed(2)}</strong><em>${signed(item.change_pct)}</em></button>`).join('')}</div></section>`).join(''); document.querySelectorAll('.qt-tile').forEach(tile => tile.onclick = () => selectSymbol(tile.dataset.symbol)); };
  const loadMap = async () => { $('qtCloud').innerHTML = '<div class="qt-empty">正在加载市场云图…</div>'; try { renderMap(await request('/api/quant/market-map')); } catch(error) { $('qtCloud').innerHTML = `<div class="qt-error">${escapeHtml(error.message)}</div>`; } };
  const loadSentiment = async () => { const target=$('qtSentiment'); target.innerHTML='<div class="qt-empty">正在加载情绪数据…</div>'; try { const data=await request('/api/quant/sentiment'); const ladder=data.ladder.length?data.ladder.map(item=>`<span>${item.days}板 <b>${item.count}</b></span>`).join(''):'暂无连板数据'; target.innerHTML=`<div class="qt-moodcards"><div><small>涨停</small><strong class="up">${data.limit_up}</strong></div><div><small>炸板</small><strong>${data.open_board}</strong></div><div><small>跌停</small><strong class="down">${data.limit_down}</strong></div><div><small>最高连板</small><strong>${data.max_height} 板</strong></div><div><small>炸板率</small><strong>${data.break_rate}%</strong></div></div><div class="qt-ladder"><b>连板梯队</b>${ladder}<small>${escapeHtml(data.note)}</small></div>`; } catch(error) { target.innerHTML=`<div class="qt-error">${escapeHtml(error.message)}</div>`; } };
  const runBacktest = async () => { const symbol = $('qtBacktest').dataset.symbol || $('qtSymbol').value.trim(); $('qtResult').textContent = '正在回测；不会创建任何订单…'; try { const data = await request('/api/quant/backtest', {method:'POST',body:JSON.stringify({symbol,short_window:Number($('qtShort').value),long_window:Number($('qtLong').value),initial_capital:Number($('qtCapital').value)})}); $('qtResult').innerHTML = `<b class="${data.return_pct>=0?'up':'down'}">策略 ${data.return_pct}%</b><span>买入持有 ${data.buy_hold_return_pct}%</span><span>最大回撤 ${data.max_drawdown_pct}%</span><span>${data.trade_count} 次交易</span><small>${escapeHtml(data.note)}</small>`; } catch(error) { $('qtResult').textContent=error.message; } };
  const init = () => {
    if ($('quant')) return; const nav=document.querySelector('.nav'), main=document.querySelector('main'); if(!nav||!main)return; const navButton=document.createElement('button'); navButton.id='quantNav'; navButton.type='button'; navButton.innerHTML='<span>⌁</span> 量化终端'; navButton.onclick=openQuant; nav.append(navButton);
    const section=document.createElement('section'); section.id='quant'; section.className='page'; section.innerHTML=`<div class="qt-hero"><div><p class="qt-kicker">MARKET INTELLIGENCE</p><h2>市场云图 · 日 K 研究</h2><p>按主题观察大盘，点击标的即可打开专业日 K。行情仅用于研究分析，不接入券商和下单功能。</p></div><div class="qt-legend"><span><i class="rise"></i>上涨</span><span><i class="fall"></i>下跌</span><button id="qtRefresh" class="secondary">刷新云图</button></div></div><div class="qt-shell"><aside class="qt-map"><div class="qt-panelhead"><b>市场分类云图</b><small id="qtUpdated">正在加载…</small></div><div id="qtCloud" class="qt-cloud"></div></aside><article class="qt-detail"><div class="qt-toolbar"><div><p>日 K · 前复权</p><h3 id="qtSymbolTitle">选择左侧标的</h3></div><div id="qtQuote" class="qt-quote">—</div></div><div class="qt-input"><input id="qtSymbol" value="sh000300" maxlength="8" placeholder="代码：600519 / 510300 / sh000001"><button id="qtLoad" class="primary">查看日 K</button></div><div id="qtStats" class="qt-stats">点击云图中的标的，或输入股票、指数、ETF 代码。</div><div id="qtChart" class="qt-chart"><div class="qt-empty">请选择一个标的查看专业日 K</div></div><div class="qt-key"><span class="ma5">━</span> MA5 <span class="ma20">━</span> MA20 <span class="volkey">▮</span> 成交量</div><div id="qtBacktest" class="qt-backtest"><div><b>均线策略模拟</b><small>金叉/死叉次日开盘成交，不使用未来价格</small></div><label>短 <input id="qtShort" type="number" value="10" min="2" max="60"></label><label>长 <input id="qtLong" type="number" value="30" min="3" max="250"></label><label>本金 <input id="qtCapital" type="number" value="100000" min="10000" step="10000"></label><button id="qtRun" class="primary">运行回测</button></div><div id="qtResult" class="qt-result">选择标的后可运行；结果仅供研究，不构成投资建议。</div></article></div>`; main.append(section);
    const sentiment=document.createElement('section'); sentiment.id='qtSentiment'; sentiment.className='qt-sentiment'; section.querySelector('.qt-hero').after(sentiment);
    const auto=document.createElement('label'); auto.className='qt-auto'; auto.style.cssText='display:flex;align-items:center;gap:5px;white-space:nowrap'; auto.innerHTML='<input id="qtAuto" type="checkbox" checked> 自动刷新 30 秒'; auto.querySelector('input').style.cssText='width:auto;margin:0;accent-color:#2563eb'; section.querySelector('.qt-legend').prepend(auto);
    $('qtRefresh').onclick=()=>{loadMap();loadSentiment()}; $('qtLoad').onclick=()=>selectSymbol($('qtSymbol').value.trim()); $('qtRun').onclick=runBacktest; loadMap(); loadSentiment(); selectSymbol('sh000300');
    setInterval(()=>{ if(!$('qtAuto')?.checked || !$('quant')?.classList.contains('active')) return; loadMap(); if(++refreshTick%2===0){ loadSentiment(); const symbol=$('qtBacktest').dataset.symbol; if(symbol) selectSymbol(symbol); } },30000);
  };
  const style=document.createElement('style'); style.textContent=`#quant{max-width:1480px}.qt-hero{display:flex;justify-content:space-between;gap:18px;align-items:flex-end;margin-bottom:18px}.qt-kicker{letter-spacing:1.6px;color:#5577ab;font-size:11px;font-weight:800;margin:0 0 7px}.qt-hero h2{font-size:30px;letter-spacing:-.8px;margin:0 0 7px;color:#14213a}.qt-hero p:not(.qt-kicker){color:#60708a;margin:0}.qt-legend{display:flex;align-items:center;gap:12px;font-size:12px;color:#61708a}.qt-legend i{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:4px}.rise{background:#ef5350}.fall{background:#2ca87f}.qt-shell{display:grid;grid-template-columns:minmax(340px,.9fr) minmax(560px,1.55fr);gap:16px}.qt-map,.qt-detail{background:#fff;border:1px solid #e0e7f0;border-radius:16px;box-shadow:0 8px 25px #1235680b}.qt-panelhead{padding:17px 18px 12px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #ecf0f6}.qt-panelhead small{font-size:11px;color:#7b889b}.qt-cloud{padding:8px 14px 16px}.qt-sector{padding:13px 0;border-bottom:1px solid #edf1f6}.qt-sector:last-child{border:0}.qt-sector header{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;font-size:13px}.qt-sector header b{color:#34425a}.up{color:#e44f56!important}.down{color:#22946d!important}.qt-tilegrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.qt-tile{padding:10px 9px;border:1px solid transparent;border-radius:9px;text-align:left;background:#f4faf7;transition:transform .15s,border-color .15s}.qt-tile:hover{transform:translateY(-1px);border-color:#b8cadf}.qt-tile.rise{background:#fff3f1}.qt-tile.fall{background:#edf9f3}.qt-tile small,.qt-tile strong,.qt-tile em{display:block}.qt-tile small{font-size:11px;color:#526077;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.qt-tile strong{font-size:16px;color:#243247;margin:3px 0}.qt-tile em{font-size:12px;font-style:normal}.qt-detail{padding:0;overflow:hidden;background:#fff}.qt-toolbar{padding:17px 20px 12px;display:flex;justify-content:space-between;align-items:center}.qt-toolbar p{font-size:11px;letter-spacing:.8px;font-weight:700;color:#6a7a93;margin:0}.qt-toolbar h3{font-size:20px;margin:5px 0 0}.qt-quote{text-align:right}.qt-quote strong{display:block;font-size:22px;color:#23314a}.qt-quote span{font-size:13px;margin-right:8px}.qt-quote em{display:block;color:#76849a;font-size:11px;font-style:normal;margin-top:3px}.qt-input{display:flex;gap:8px;padding:0 20px 13px}.qt-input input{border-radius:8px}.qt-input button{white-space:nowrap}.qt-stats{border-top:1px solid #eef1f6;padding:9px 20px;display:flex;gap:16px;flex-wrap:wrap;font-size:12px;color:#5c6c84}.qt-chart{padding:0 14px;background:#0c1729}.qt-canvas{display:block;width:100%;height:auto;min-height:300px}.qt-empty,.qt-error{padding:30px;color:#8294b1;text-align:center}.qt-error{color:#ef797d;background:#351d29}.qt-key{background:#0c1729;color:#a7b7d3;padding:0 20px 14px;font-size:11px;display:flex;gap:7px;align-items:center}.ma5{color:#f5b942}.ma20{color:#52b5ff}.volkey{color:#9ba9be}.qt-backtest{padding:15px 20px;display:flex;gap:9px;align-items:end;flex-wrap:wrap;border-top:1px solid #e9edf4}.qt-backtest>div{margin-right:auto}.qt-backtest b,.qt-backtest small{display:block}.qt-backtest small{font-size:11px;color:#748198;margin-top:4px}.qt-backtest label{font-size:11px;color:#66758b;display:grid;gap:4px}.qt-backtest input{width:90px;padding:7px}.qt-backtest button{padding:9px 12px}.qt-result{padding:12px 20px 18px;display:flex;gap:14px;align-items:center;flex-wrap:wrap;font-size:12px;color:#5b6a7d}.qt-result b{font-size:16px}.qt-result small{width:100%;color:#8793a5}@media(max-width:1050px){.qt-shell{grid-template-columns:1fr}.qt-tilegrid{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:650px){.qt-hero{align-items:start;flex-direction:column}.qt-tilegrid{grid-template-columns:repeat(2,minmax(0,1fr))}.qt-toolbar{padding:15px}.qt-backtest>div{width:100%}.qt-legend{flex-wrap:wrap}}`; document.head.append(style);
  const moodStyle=document.createElement('style'); moodStyle.textContent=`.qt-sentiment{background:#fff;border:1px solid #e0e7f0;border-radius:16px;box-shadow:0 8px 25px #1235680b;margin-bottom:16px;padding:14px 18px}.qt-moodcards{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.qt-moodcards div{border-right:1px solid #edf1f6;padding:2px 12px}.qt-moodcards div:first-child{padding-left:0}.qt-moodcards div:last-child{border:0}.qt-moodcards small,.qt-moodcards strong{display:block}.qt-moodcards small{color:#748198;font-size:11px}.qt-moodcards strong{font-size:22px;margin-top:5px}.qt-ladder{margin-top:12px;padding-top:11px;border-top:1px solid #edf1f6;display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:12px;color:#56657a}.qt-ladder span{background:#f1f5fa;padding:5px 8px;border-radius:6px}.qt-ladder small{color:#8b97a8;margin-left:auto}@media(max-width:650px){.qt-moodcards{grid-template-columns:repeat(3,1fr)}.qt-moodcards div{border:0;padding:5px 0}.qt-ladder small{margin-left:0;width:100%}}`; document.head.append(moodStyle);
  document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init):init();
})();

// Native MyAgent cockpit skin: Tick Stock Panel is only a visual reference;
// this layer keeps the existing MyAgent data and endpoints in control.
(() => {
  const mount = () => {
    const root = document.querySelector('#quant');
    if (!root || root.querySelector('.qt-terminalbar')) return;
    const hero = root.querySelector('.qt-hero');
    if (!hero) return;
    hero.insertAdjacentHTML('beforebegin', `<div class="qt-terminalbar"><div class="qt-terminal-title"><span class="qt-live-dot"></span><b>MyAgent 量化看盘</b><small>研究终端 · 不自动下单</small></div><div class="qt-terminal-tabs"><button class="active" type="button">市场总览</button><button type="button">拾贝模型</button><button type="button">持仓做T</button><button type="button">板块热力</button></div><div class="qt-terminal-actions"><span id="qtMarketClock">行情连接中</span><button id="qtCompact" type="button">紧凑布局</button></div></div><div class="qt-dashboard-strip"><div><small>市场情绪</small><strong>—</strong><span>涨停 / 跌停 —</span></div><div><small>上涨家数</small><strong>—</strong><span>公开行情快照</span></div><div><small>下跌家数</small><strong>—</strong><span>公开行情快照</span></div><div><small>当前模型</small><strong>拾贝</strong><span>长期地量 → 放量异动</span></div><div><small>实时能力</small><strong>公开行情</strong><span>接入 QMT 后升级</span></div></div>`);
    const style = document.createElement('style');
    style.textContent = `.qt-terminalbar{display:flex;align-items:center;gap:18px;min-height:48px;margin:-12px -14px 14px;padding:0 14px;background:#0b1624;color:#dce8f5;border-bottom:1px solid #20364a}.qt-terminal-title{display:flex;align-items:center;gap:8px;white-space:nowrap}.qt-terminal-title small{color:#71869b;font-size:10px}.qt-live-dot{width:7px;height:7px;border-radius:50%;background:#20c58b;box-shadow:0 0 0 4px #20c58b22}.qt-terminal-tabs{display:flex;align-self:stretch;gap:2px}.qt-terminal-tabs button{border:0;border-bottom:2px solid transparent;background:transparent;color:#8298ae;padding:0 12px;cursor:pointer}.qt-terminal-tabs button.active,.qt-terminal-tabs button:hover{color:#fff;border-color:#3292ff;background:#10263a}.qt-terminal-actions{display:flex;align-items:center;gap:10px;margin-left:auto;color:#6f8499;font-size:11px}.qt-terminal-actions button{border:1px solid #2b4962;background:#102033;color:#a9bdcf;padding:5px 8px;border-radius:3px}.qt-dashboard-strip{display:grid;grid-template-columns:repeat(5,minmax(130px,1fr));gap:1px;margin-bottom:14px;background:#21364a;border:1px solid #21364a}.qt-dashboard-strip>div{min-height:66px;padding:9px 12px;background:#0c1825}.qt-dashboard-strip small,.qt-dashboard-strip strong,.qt-dashboard-strip span{display:block}.qt-dashboard-strip small{color:#6e8499;font-size:10px}.qt-dashboard-strip strong{margin:3px 0;font-size:17px;color:#edf5fc}.qt-dashboard-strip span{color:#8095aa;font-size:10px}.qt-dashboard-strip>div:first-child strong{color:#f5b94b}@media(max-width:900px){.qt-terminalbar{flex-wrap:wrap;padding:8px 10px}.qt-terminal-tabs{order:3;width:100%;overflow:auto;height:34px}.qt-terminal-actions{margin-left:auto}.qt-dashboard-strip{grid-template-columns:repeat(3,1fr)}}@media(max-width:600px){.qt-dashboard-strip{grid-template-columns:repeat(2,1fr)}.qt-terminal-title small,.qt-terminal-actions span{display:none}}`;
    document.head.append(style);
    const compact = root.querySelector('#qtCompact');
    compact?.addEventListener('click', () => root.classList.toggle('qt-compact'));
    const clock = root.querySelector('#qtMarketClock');
    const tick = () => { if (clock) clock.textContent = `行情 ${new Date().toLocaleTimeString('zh-CN',{hour12:false})}`; };
    tick(); setInterval(tick, 1000);
  };
  const observer = new MutationObserver(mount);
  observer.observe(document.body, {childList:true, subtree:true});
  mount();
})();

// Lightweight chart navigation for the native SVG chart: wheel zoom + drag pan.
(() => {
  const bind = () => {
    const svg = document.querySelector('#qtChart svg.qt-canvas');
    if (!svg || svg.dataset.navBound) return;
    svg.dataset.navBound = '1';
    let zoom = 1, offset = 0, startX = 0, startOffset = 0, dragging = false;
    const width = 1000;
    const apply = () => {
      const visible = width / zoom;
      const maxOffset = Math.max(0, width - visible);
      offset = Math.min(Math.max(offset, 0), maxOffset);
      svg.setAttribute('viewBox', `${offset} 0 ${visible} 440`);
    };
    svg.style.cursor = 'grab';
    svg.addEventListener('wheel', event => {
      event.preventDefault();
      zoom = Math.min(4, Math.max(1, zoom * (event.deltaY < 0 ? 1.18 : .85)));
      apply();
    }, {passive:false});
    svg.addEventListener('pointerdown', event => { dragging = true; startX = event.clientX; startOffset = offset; svg.style.cursor = 'grabbing'; svg.setPointerCapture?.(event.pointerId); });
    svg.addEventListener('pointermove', event => { if (!dragging) return; const visible = width / zoom; offset = startOffset - (event.clientX - startX) / Math.max(svg.clientWidth, 1) * visible; apply(); });
    const stop = () => { dragging = false; svg.style.cursor = 'grab'; };
    svg.addEventListener('pointerup', stop); svg.addEventListener('pointercancel', stop);
    apply();
  };
  const observer = new MutationObserver(bind);
  observer.observe(document.body, {childList:true, subtree:true});
  bind();
})();
